"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["38499"],{78583(e,t,o){o.r(t),o.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>h});var a=JSON.parse('{"id":"qiangguo/lhzdeath","title":"","description":"Recently, a certain Mr. Li surnamed elder passed his hundredth year. The elites, rendered incoherent by grief, went so far as to invoke the concept of daotong -- the transmission of the orthodox Way, which surfaced starting with Han Yu -- from the mouths of 21st-century elites who pride themselves on Westernization. Quite a spectacle. What virtue and ability did old Mr. Li possess to warrant such a fuss from the elites? Not being one for celebrity worship, I couldn\'t be bothered to verify. But by coincidence, I happened upon an article by one of his great disciples, containing old Mr. Li\'s discourse on equality and freedom. This disciple had an epiphany because of it and served him faithfully for life. Such a remarkable argument deserves to be shared for all to examine.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/lhzdeath.md","sourceDirName":"qiangguo","slug":"/qiangguo/lhzdeath","permalink":"/en/qiangguo/lhzdeath","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"lhzdeath","title":"","hide_table_of_contents":true,"sidebar_label":"On equality and freedom, from the death of old man Li"},"sidebar":"qiangguoSidebar","previous":{"title":"From a poem by that old thief Li Hongzhang, examining the basic traits and tricks of all wolves in sheep\'s clothing","permalink":"/en/qiangguo/lhzhumanbeast"},"next":{"title":"In handling the D\'Long Group crisis, the Chinese government will face a major test","permalink":"/en/qiangguo/delongfaction"}}'),n=o(74848),i=o(28453);let s={id:"lhzdeath",title:"",hide_table_of_contents:!0,sidebar_label:"On equality and freedom, from the death of old man Li"},r="On Equality and Freedom, from the Death of Old Mr. Li",h={},l=[];function d(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"on-equality-and-freedom-from-the-death-of-old-mr-li",children:"On Equality and Freedom, from the Death of Old Mr. Li"})}),"\n",(0,n.jsx)(t.p,{children:"Recently, a certain Mr. Li surnamed elder passed his hundredth year. The elites, rendered incoherent by grief, went so far as to invoke the concept of daotong -- the transmission of the orthodox Way, which surfaced starting with Han Yu -- from the mouths of 21st-century elites who pride themselves on Westernization. Quite a spectacle. What virtue and ability did old Mr. Li possess to warrant such a fuss from the elites? Not being one for celebrity worship, I couldn't be bothered to verify. But by coincidence, I happened upon an article by one of his great disciples, containing old Mr. Li's discourse on equality and freedom. This disciple had an epiphany because of it and served him faithfully for life. Such a remarkable argument deserves to be shared for all to examine."}),"\n",(0,n.jsx)(t.p,{children:"Old Mr. Li's thesis was roughly this: capitalism values freedom, socialism values equality, and without freedom, one does not even have the possibility of freely pursuing equality -- so where would equality come from? Therefore freedom precedes equality. According to this disciple, this thesis was old Mr. Li's enlightenment after much tribulation, and constituted the very foundation of his thought."}),"\n",(0,n.jsx)(t.p,{children:'However, freedom has never been free. Freedom -- one must first have a "self" from which to "proceed." Without self, what proceeds? With self, proceeds to what? Furthermore, so-called freedom in reality has never been free. So-called free will is in substance the product of all manner of unfree processes. Presumably what the elites resent most is that their so-called free will failed, at the moment of their conception, to stamp itself with a MADE IN USA mark -- truly unfortunate. On the other hand, if one truly understands "Who binds you?" or "The vast sky does not obstruct the white clouds\' flight," then all talk of "freely" or "unfreely" becomes superfluous. What would there be to say about freely pursuing anything? In other words, regardless of the premise, "freely pursuing something" is always nonsense, because freedom has never existed or has never needed to exist.'}),"\n",(0,n.jsx)(t.p,{children:"That freedom has never needed to exist is the realm of Chan enlightenment, which we shall set aside for the mundane world. That freedom has never existed -- beyond what was discussed above -- can also be illuminated by \"man is the totality of all social relations.\" No matter how sacred the elites' fantasized freedom may be, in reality it dissolves into a pile of not-so-beautiful relations and outcomes. Freedom has never existed, yet this also means that a certain kind of real freedom manifested in social relations has always existed -- it's just that for certain types of people there is too much, and for others too little."}),"\n",(0,n.jsx)(t.p,{children:"Regardless, that conceptualized, verbalized freedom will continue to be the elites' tool for making a living. I won't smash this cracked pot any further -- swindlers are a dime a dozen anyway, a few more won't make a difference. Consider it maintaining biodiversity. But peering through the fog of concepts and slogans, within real social relations, making the various real freedoms that have always existed -- though too plentiful for some and too scarce for others -- more equal and just: this is the crux of the matter."})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,t,o){o.d(t,{R:()=>s,x:()=>r});var a=o(96540);let n={},i=a.createContext(n);function s(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);